CREATE DATABASE IF NOT EXISTS placement_portal; USE placement_portal;
CREATE TABLE IF NOT EXISTS students (id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,roll_number VARCHAR(40) NOT NULL UNIQUE,department VARCHAR(80) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,mobile VARCHAR(20) NOT NULL,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_student_email(email));
CREATE TABLE IF NOT EXISTS aptitude_questions (id INT AUTO_INCREMENT PRIMARY KEY,question TEXT NOT NULL,option_a VARCHAR(255) NOT NULL,option_b VARCHAR(255) NOT NULL,option_c VARCHAR(255) NOT NULL,option_d VARCHAR(255) NOT NULL,correct_answer CHAR(1) NOT NULL,INDEX idx_questions_answer(correct_answer));
CREATE TABLE IF NOT EXISTS test_results (id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,total_questions INT NOT NULL,attempted_questions INT NOT NULL,correct_answers INT NOT NULL,wrong_answers INT NOT NULL,final_score INT NOT NULL,percentage DECIMAL(5,2) NOT NULL,completed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,INDEX idx_results_student(student_id));
INSERT INTO aptitude_questions (question,option_a,option_b,option_c,option_d,correct_answer) VALUES ('If 5x = 45, what is x?','5','7','9','11','C'),('A train travels 120 km in 2 hours. Its speed is?','40 km/h','60 km/h','80 km/h','120 km/h','B'),('What is 20% of 250?','25','40','50','75','C'),('Find the next number: 2, 4, 8, 16, ?','20','24','30','32','D'),('A shop offers 10% discount on ₹500. Sale price?','₹450','₹460','₹490','₹550','A'),('Which is a prime number?','21','29','39','51','B'),('Average of 10 and 20 is?','10','15','20','30','B'),('If today is Monday, after 10 days it is?','Wednesday','Thursday','Friday','Sunday','B'),('Ratio 2:3 has total 25. Smaller part?','8','10','12','15','B'),('Simple interest on ₹1000 at 5% for 2 years?','₹50','₹100','₹150','₹200','B') ON DUPLICATE KEY UPDATE question=VALUES(question);
